// Assemble the Nullbyte Security theme (6 Divi 5 pages for a penetration-testing and cybersecurity consultancy) into one pack. Unlike create-real-estate-pack.ts the pages are NOT
// generated by the pipeline's Claude workers: they are composed by the AI Editor for
// Divi 5 plugin from its section recipes (design language organic-warm + a style kit,
// validated by the real LayoutGate) in the validator repo:
//   php scripts/theme-packs/build.php nullbyte      -> dist/theme-packs/nullbyte/<role>.json
// and then run through every downstream gate here (validate, stock photos, design lint,
// mobile stacking, dedupe, SEO, real Divi render, critics, ingest).
//
//   npm run dev            # in another shell (ingest target)
//   set -a && . ./.env.local && set +a && NLB_DIR=<dir with the six json files> npx tsx scripts/create-nullbyte-pack.ts
// Smoke test: THEME_ONLY_ROLES=home.
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { eq, inArray } from 'drizzle-orm';
import { db } from '@/db/client';
import { packs, packLayouts, layouts } from '@/db/schema';
import { buildThemeDeps } from '@/pipeline/deps';
import { runThemePack, themePageSlug, type ThemeSpec, type ThemePage } from '@/pipeline/theme';
import type { Brief } from '@/pipeline/compose';

const DIR = process.env.NLB_DIR ?? '../Divi 5 Deterministic Validator/dist/theme-packs/nullbyte';

const BRIEF: Brief = {
  businessType: 'service/agency',
  businessName: 'Nullbyte Security',
  tagline: 'We break in, so they cannot.',
  audience: 'CTOs, CISOs and heads of engineering who need a penetration test, cloud review or incident response from senior testers who write plain English',
  conversionGoal: 'book a scoping call',
  primaryCta: 'Book a scoping call',
  accentColorHex: '#3DFF9A',
  voice: 'precise, dry and plain-spoken. Short sentences, concrete numbers, no fear-mongering and no hacker clichés.',
  palette: { primary: '#3dff9a', secondary: '#8d9892', tint: '#131715', dark: '#0b0d0c', heading: '#e8ece9', body: '#8d9892' },
  designNotes: 'Tech-mono design language: near-black backgrounds, a monospace body face, one neon green accent, hairline dashed borders and strict grids with no softness.',
};

const BRAND_FACTS =
  'Nullbyte Security, 1100 Pike Street, Suite 400, Seattle, WA 98101. Phone (206) 555-0147. hello@nullbyte.security. ' +
  'Sample copy: names, prices and reviews are examples to replace.';

const ROLES: { role: string; roleLabel: string }[] = [
  { role: 'home', roleLabel: 'Home' },
  { role: 'services', roleLabel: 'Services' },
  { role: 'approach', roleLabel: 'Approach' },
  { role: 'research', roleLabel: 'Research' },
  { role: 'about', roleLabel: 'About' },
  { role: 'contact', roleLabel: 'Contact' },
];

const PAGES: ThemePage[] = ROLES.map((r) => ({
  ...r,
  flow: [],
  precomposed: readFileSync(`${DIR}/${r.role}.json`, 'utf8'),
}));

const SPEC: ThemeSpec = { niche: 'cybersecurity', style: 'dark', color: 'green', brief: BRIEF, brandFacts: BRAND_FACTS, pages: PAGES };

const PACK_SLUG = 'nullbyte-cybersecurity-theme';
const PACK_TITLE = 'Nullbyte: Cybersecurity & Tech Consultancy Theme (6 Pages)';
const PRICE_CENTS = 1200;
const DESCRIPTION =
  'A complete six-page Divi 5 website for a cybersecurity consultancy, penetration-testing firm, developer-tools company or ' +
  'any technical B2B service, ready to make your own. Home, Services, Approach, Research, About and Contact share one ' +
  'precise, engineered identity: near-black backgrounds, a monospace body face, a single neon green accent and hairline ' +
  'dashed borders. Every section is built from proven, validated recipes and a single design language and style kit, so ' +
  'buttons, accordions, forms and type match on every page, on desktop, tablet and phone. A spec-sheet hero, a track-record ' +
  'figures band, a services bento, an engagement timeline, a scanner-versus-human comparison, point-in-time and continuous ' +
  'pricing, a research page with press quotes, a team page with a founder note, FAQs and a contact form are all in place. ' +
  'Names, prices, hours and reviews are sample copy: swap in your own and publish. No lorem ipsum, no broken layouts. One ' +
  'simple commercial license, unlimited client sites.';
const PACK_SEO = {
  metaTitle: 'Nullbyte: Cybersecurity Theme for Divi 5 (6 Pages) | Divi5Lab',
  metaDescription:
    'A complete six-page dark Divi 5 website theme for a cybersecurity or tech consultancy: Home, Services, Approach, ' +
    'Research, About and Contact. One precise brand, real copy, pricing and scoping sections.',
  keywords: [
    'divi 5 cybersecurity theme', 'penetration testing website template', 'dark tech divi template', 'security consultancy divi 5 theme',
    'it services website template', 'divi 5 multi-page theme',
  ],
};

async function upsertPack(slugs: string[]): Promise<void> {
  const rows = await db
    .select({ id: layouts.id, slug: layouts.slug, previews: layouts.previewImageKeys })
    .from(layouts).where(inArray(layouts.slug, slugs));
  const bySlug = new Map(rows.map((r) => [r.slug, r]));
  const found = slugs.filter((s) => bySlug.has(s));
  if (found.length === 0) { console.error('no Nullbyte pages found in DB — did ingest run?'); process.exitCode = 1; return; }
  if (found.length < slugs.length) console.warn(`only ${found.length}/${slugs.length} pages present; linking what exists`);

  const cover = bySlug.get(slugs[0])?.previews?.[0] ?? bySlug.get(found[0])!.previews?.[0] ?? null;
  const existing = (await db.select().from(packs).where(eq(packs.slug, PACK_SLUG)).limit(1))[0];
  const common = {
    title: PACK_TITLE, description: DESCRIPTION, kind: 'paid' as const,
    priceCents: PRICE_CENTS, stripePriceId: null, coverImageKey: cover, seo: PACK_SEO, status: 'published' as const,
  };
  let packId: string;
  if (existing) {
    packId = existing.id;
    await db.update(packs).set(common).where(eq(packs.id, packId));
  } else {
    packId = randomUUID();
    await db.insert(packs).values({ id: packId, slug: PACK_SLUG, ...common });
  }

  await db.delete(packLayouts).where(eq(packLayouts.packId, packId));
  await db.insert(packLayouts).values(found.map((s, i) => ({ packId, layoutId: bySlug.get(s)!.id, position: i })));

  console.log(`\nPack ready: /packs/${PACK_SLUG}  (paid, ${found.length} pages, cover=${cover ? 'set' : 'none'})`);
}

async function main() {
  const { deps, close } = await buildThemeDeps({ businessName: BRIEF.businessName, logPrefix: '[theme]', defaultMaxBudgetUsd: 1 });

  // Optional smoke-test knob: THEME_ONLY_ROLES=home,listings limits which pages generate.
  const onlyRoles = (process.env.THEME_ONLY_ROLES ?? '').split(',').map((s) => s.trim()).filter(Boolean);
  const spec: ThemeSpec = onlyRoles.length ? { ...SPEC, pages: SPEC.pages.filter((p) => onlyRoles.includes(p.role)) } : SPEC;

  console.log(`[theme] generating ${spec.pages.length} ${spec.niche} pages for "${BRIEF.businessName}"…`);
  const result = await runThemePack(spec, deps);
  await close();
  console.log('[theme] summary:', { generated: result.generated, ingested: result.ingested, dropped: result.dropped, deduped: result.deduped });

  if (onlyRoles.length) { console.log('[theme] partial run (THEME_ONLY_ROLES set) — skipping pack assembly'); return; }
  const expectedSlugs = SPEC.pages.map((p) => themePageSlug(BRIEF, SPEC, p));
  await upsertPack(expectedSlugs);
}

main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });
